import json,re
out=[]
def add(cat,group,name,desc='',risk='Safe',impact='medium',changes=None,kind=None,package='',explain='',admin=False,reboot=False):
    key=re.sub('[^a-z0-9]+','-',name.lower()).strip('-')
    id=cat+'-'+key
    kind=kind or ('registry' if changes else 'preview')
    out.append(dict(id=id,category=cat,group=group,name=name,description=desc or 'Review this Windows tuning option.',risk=risk,impact=impact,kind=kind,changes=changes or [],package=package,explain=explain or ('This tweak depends on Windows version and hardware. It is shown for reference only to avoid unreliable or destructive changes.' if kind=='preview' else ''),admin=admin,reboot=reboot))
def reg(key,name,typ,val): return dict(key=key,name=name,type=typ,value=val)
D=r'HKCU\Control Panel\Desktop'; R=r'HKCU\Software\Microsoft\Windows\CurrentVersion'; E=R+r'\Explorer'; G=R+r'\GameDVR'; A=R+r'\AdvertisingInfo'
G1='Visual & Responsiveness';G2='Power & Latency'
add('general',G1,'Disable visual effects & animations','Turns off Windows minimize/maximize animations and visual effects.','Safe','high',[reg(D+r'\WindowMetrics','MinAnimate','REG_SZ','0'),reg(E+r'\VisualEffects','VisualFXSetting','REG_DWORD','2')])
add('general',G1,'Reduce menu show delay','Sets MenuShowDelay to 20 ms for faster menus.','Safe','medium',[reg(D,'MenuShowDelay','REG_SZ','20')])
add('general',G1,'Disable transparency effects','Turns off acrylic and Mica blur in supported Windows UI.','Safe','medium',[reg(R+r'\Themes\Personalize','EnableTransparency','REG_DWORD','0')])
add('general',G1,'Disable startup delay','Removes the artificial startup app delay.','Safe','medium',[reg(E+r'\Serialize','StartupDelayInMSec','REG_DWORD','0')])
add('general',G2,'Ultimate Performance power plan','Creates and activates a power plan, with an explicit restore option.','Caution','high',explain='Power plans can increase power use, heat and fan noise. Choose your plan in Windows Power & Battery settings.')
add('general',G2,'Disable core parking','Avoids parked CPU cores; may increase temperatures.','Caution','high',explain='Aggressive core-parking adjustments are not universally beneficial. Use Windows power plan settings for your hardware.')
add('general',G2,'Disable USB selective suspend','Keeps USB devices awake; may increase power consumption.','Caution','medium',explain='Prefer changing USB power management per-device in Windows Device Manager.')
add('general',G2,'Win32PrioritySeparation tuning','Scheduling bias toward foreground applications.','Caution','high',explain='Scheduler registry tweaks are workload-specific and can worsen input responsiveness.')
add('general',G1,'Disable Filter Keys','Avoids accessibility key filtering during gaming.','Safe','medium',[reg(r'HKCU\Control Panel\Accessibility\Keyboard Response','Flags','REG_SZ','122')])
add('general',G1,'Disable Sticky Keys prompt','Stops Shift hotkey from opening Sticky Keys prompts.','Safe','medium',[reg(r'HKCU\Control Panel\Accessibility\StickyKeys','Flags','REG_SZ','506')])
add('general',G1,'Disable remote scheduled tasks scan','May speed up remote folder browsing.','Safe','medium',explain='Explorers network behavior differs between Windows releases; use policy controls if relevant.')
add('general',G1,'Disable shortcut resolution search','Avoids searching for the target of broken shortcuts.','Safe','medium',explain='The legacy policy is not consistently supported across modern Windows builds.')
add('general',G2,'Maximise keyboard repeat rate','Sets repeat rate to 31 (fastest).','Safe','medium',[reg(r'HKCU\Control Panel\Keyboard','KeyboardSpeed','REG_SZ','31')])
add('general',G2,'Remove keyboard repeat delay','Sets initial repeat delay to minimum.','Safe','medium',[reg(r'HKCU\Control Panel\Keyboard','KeyboardDelay','REG_SZ','0')])
add('general',G1,'Run folders in separate processes','Uses a separate Explorer process for folder windows.','Safe','low',[reg(E+r'\Advanced','SeparateProcess','REG_DWORD','1')])
add('general',G2,'Set mouse sensitivity to 6/11','Sets classic Windows pointer speed to 10.','Safe','medium',[reg(r'HKCU\Control Panel\Mouse','MouseSensitivity','REG_SZ','10')])
add('general',G2,'Flatten mouse X curve','Disables classic Windows pointer acceleration.','Caution','medium',[reg(r'HKCU\Control Panel\Mouse','MouseSpeed','REG_SZ','0'),reg(r'HKCU\Control Panel\Mouse','MouseThreshold1','REG_SZ','0'),reg(r'HKCU\Control Panel\Mouse','MouseThreshold2','REG_SZ','0')])
add('general',G2,'Flatten mouse Y curve','Turns off mouse acceleration on both axes.','Caution','medium',explain='The X/Y acceleration curves are not independent in modern Windows; use the mouse acceleration option instead.')
for n,d in [
('Tune keyboard data queue','Legacy keyboard class driver queue tweak.'),('Tune mouse data queue','Legacy mouse class driver queue tweak.'),('Auto-end hung tasks','Automatically closing unresponsive apps can discard unsaved work.'),('Block SendInput resets','Not recommended; may interfere with input injection.'),('Disable Aero Peek','Hides desktop preview on taskbar hover.'),('Disable Aero Shake','Stops shake-to-minimize.')]:
    add('general',G1,n,d,'Caution' if 'Auto-end' in n else 'Safe','low')

B1='Pre-installed Apps';B2='Telemetry & Tracking';B3='Background & Startup Bloat';B4='Aggressive — Advanced users only'
add('debloating',B1,'Remove Xbox Game Bar & DVR','Disables capture and recording features, keeping Xbox dependencies installed.','Safe','high',[reg(r'HKCU\System\GameConfigStore','GameDVR_Enabled','REG_DWORD','0'),reg(G,'AppCaptureEnabled','REG_DWORD','0')])
add('debloating',B1,'Remove Cortana','Optional current-user app removal; not installed on many Windows builds.','Caution','low',kind='appx',package='Microsoft.549981C3F5F10')
add('debloating',B1,'Strip OneDrive integration','Hide OneDrive in Windows if you do not use cloud syncing.','Caution','medium',explain='Removing sync integration may break backup workflows. Unlink OneDrive or uninstall it using Windows Apps.')
add('debloating',B1,'Remove bundled bloat apps','Review and remove optional apps individually in App Removal.','Safe','medium',explain='Use App Removal to select optional Microsoft Store apps rather than removing them all blindly.')
add('debloating',B2,'Disable Windows telemetry','Reduces tailored diagnostic experiences, not all diagnostic collection.','Safe','medium',[reg(r'HKCU\Software\Microsoft\Windows\CurrentVersion\Privacy','TailoredExperiencesWithDiagnosticDataEnabled','REG_DWORD','0')])
add('debloating',B2,'Disable advertising ID','Disables the per-user personalized advertising identifier.','Safe','medium',[reg(A,'Enabled','REG_DWORD','0')])
add('debloating',B2,'Disable activity feed / timeline','Disable activity tracking in Windows settings.','Safe','low',explain='Activity history controls have changed in Windows 10/11. Review Settings → Privacy & security → Activity history.')
add('debloating',B2,'Block telemetry endpoints (hosts)','Modifies hosts file for known telemetry domains.','Caution','medium',explain='Hosts-file blocks can accidentally break Windows services, authentication or updates; not automated.')
add('debloating',B3,'Disable Edge background processes','Stops Edge background mode and Startup Boost via user policies.','Safe','high',[reg(r'HKCU\Software\Policies\Microsoft\Edge','BackgroundModeEnabled','REG_DWORD','0'),reg(r'HKCU\Software\Policies\Microsoft\Edge','StartupBoostEnabled','REG_DWORD','0')])
add('debloating',B3,'Disable app restart on sign-in','Windows reopens supported apps after sign-in.','Safe','medium',explain='Use Settings → Accounts → Sign-in options → Automatically save my restartable apps.')
add('debloating',B3,'Disable Widgets','Hides Widgets on supported Windows 11 taskbars.','Safe','medium',[reg(E+r'\Advanced','TaskbarDa','REG_DWORD','0')])
add('debloating',B3,'Disable telemetry scheduled tasks','Scheduled diagnostic tasks can be required for issue reports.','Caution','medium',explain='Disabling broad diagnostics can hinder troubleshooting and Windows stability.')
add('debloating',B4,'Uninstall Microsoft Edge','Force-removal can break WebView-based apps and updates.','Advanced','high',explain='Intentionally disabled. Removing Edge can break Windows features, including this application’s app-mode window.')
add('debloating',B4,'Block auto-restart when logged in','Requires edition-specific Windows Update policies.','Caution','high',explain='Use Settings → Windows Update → Advanced options → Active hours to prevent disruptive reboots safely.')
add('debloating',B4,'Disable peer update sharing','Disables Windows Update delivery optimization upload.','Safe','medium',[reg(r'HKCU\Software\Microsoft\Windows\CurrentVersion\DeliveryOptimization','SystemSettingsDownloadMode','REG_DWORD','0')])
add('debloating',B4,'Exclude drivers from Windows Update','Use device-driver update policy.','Caution','medium',explain='Blocking driver updates can leave security or stability fixes unapplied.')
for n,d in [
('Defer feature updates','Defers major OS upgrades.'),('Defer features for a year','Lengthy upgrade deferral may miss security improvements.'),('Disable Bing in Start search','Removes web suggestions from Start on supported Windows builds.'),('Disable Bing web search','Blocks Start menu web results.'),('Disable CEIP Consolidator','Disables telemetry upload task.'),('Disable Compatibility Appraiser','Stops compatibility assessment scheduling.'),('Disable DiagTrack autologger','Disables system diagnostic logging.'),('Disable Store auto-updates','Disables automatic app updates.'),('Disable WinSAT assessment','Disables Windows performance assessment task.'),('Disable consumer features','Hides recommended consumer content.'),('Disable silent app installs','Stops provisioned app installs; could affect Store.'),('Disable telemetry policy','Machine-wide diagnostic data policy.'),('Remove advertising suggestions','Removes suggested apps and advertisements.'),('Remove Windows tips','Hides Windows tips and tricks.'),('Disable Start recommendations','Reduces recommended content.'),('Disable lock screen suggestions','Reduces Windows Spotlight tips.'),('Remove Game DVR scheduled tasks','Avoids background game recording tasks.'),('Disable clipboard cloud sync','Prevents clipboard sync between devices.')]:
    add('debloating',B2 if any(k in n.lower() for k in ['telemetry','diag','ceip','compatibility']) else B3,n,d,'Caution' if any(k in n.lower() for k in ['update','policy','installs']) else 'Safe','medium')

N1='Latency & Throughput';N2='DNS & Adapter'
for i,(n,d,r) in enumerate([
('Disable Nagle\'s algorithm','Sets TCPAckFrequency=1 to cut packet coalescing delay.','Caution'),('Network throttling index off','Removes the 10-packet-per-ms multimedia throttle.','Caution'),('Optimize TCP autotuning','Sets autotuning to normal for balanced window scaling.','Safe'),('Disable QoS packet scheduler reserve','Claims 20% bandwidth reserved; typically misleading.','Caution'),('Set low-latency DNS','Use Cloudflare 1.1.1.1 or Google 8.8.8.8.','Caution'),('Disable adapter power saving','Stops network adapter entering low power states.','Caution'),('Flush & optimize DNS cache','Clears DNS resolver cache (available in Fixes).','Safe'),('Disable delayed ACK','Can interact badly with modern TCP stacks.','Caution'),('Zero delayed ACK ticks','TCP ACK scheduling modification.','Caution'),('Disable Windows Scaling heuristics','Legacy TCP window heuristic policy.','Caution'),('Disable negative DNS caching','Fails lookups without caching errors.','Caution'),('Enable TCP window scaling','Modern TCP windows already enabled by default.','Safe'),('Enable selective ACK','Selective ACK recovers from packet loss.','Safe')]):
    add('networking',N2 if any(k in n.lower() for k in ['dns','adapter']) else N1,n,d,r,'high' if i in [0,1,4,7] else 'medium',explain='This change is highly dependent on the network adapter, Windows build and ISP. A generic toggle could reduce throughput or disconnect you. Review your settings rather than applying blanket registry changes.' if r=='Caution' else 'Windows already manages this in most current configurations. Use built-in tools; no unverified registry tweak is applied.')

A1='Memory & Kernel';A2='GPU & Scheduling'
for n,d,r in [
('Disable memory compression','Reduces CPU overhead but can increase RAM pressure.','Caution'),('Large system cache tuning','Server-style system file caching.','Caution'),('Disable prefetch & superfetch','Can slow application launches on SSDs.','Caution'),('Kernel timer resolution','Raises timer frequency at cost of power and sometimes FPS.','Caution'),('Hardware-accelerated GPU scheduling','Windows HAGS option, may help or worsen stutter.','Caution'),('Disable fullscreen optimizations','Some games perform worse; use per-game compatibility settings.','Safe'),('MSI mode for GPU','Changes device interrupt driver configuration.','Caution'),('Disable dynamic tick','Kernel timer behavior; no universal gaming advantage.','Caution'),('Block apps running in background','Disables background UWP apps on supported builds.','Safe'),('Disable background apps','Prevents supported Store apps from running in background.','Safe'),('Disable 8.3 filename creation','NTFS short-name support, affects old software.','Caution'),('Disable NTFS last access updates','Reduces metadata updates.','Safe'),('Don\'t clear pagefile at shutdown','Avoids slow shutdowns, usually already the default.','Safe'),('Keep TRIM enabled','Maintains SSD health and speed; already usually enabled.','Safe'),('Disable Connected Standby','May break modern laptop sleep.','Caution'),('Disable Modern Standby','Changes laptop power behavior.','Caution'),('Disable Network Data Usage driver','Can break network data metering.','Caution'),('Distribute timers across cores','Changes interrupt scheduling.','Caution'),('Keep kernel in physical memory','Legacy DisablePagingExecutive tweak.','Caution'),('Serialise timer expiration','Timer expiration behavior.','Caution')]:
    changes=None
    if n=='Block apps running in background' or n=='Disable background apps': changes=[reg(r'HKCU\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications','GlobalUserDisabled','REG_DWORD','1')]
    if n=='Disable NTFS last access updates':
        changes=None
    if n=='Don\'t clear pagefile at shutdown':
        changes=[reg(r'HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','ClearPageFileAtShutdown','REG_DWORD','0')]
    if n=='Hardware-accelerated GPU scheduling':
        changes=[reg(r'HKLM\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode','REG_DWORD','2')]
    add('advanced',A2 if any(k in n.lower() for k in ['gpu','fullscreen','msi','driver']) else A1,n,d,r,'high' if r=='Caution' else 'medium',changes,admin=bool(changes and 'HKLM' in changes[0]['key']),reboot=bool(changes and 'HKLM' in changes[0]['key']))

for n,d in [('Trim startup bloat','Use Resources to review startup items one by one.'),('Set launcher priorities','Boosts game launchers, throttles background updaters.'),('Suspend idle background apps','Stops idle applications without losing data.')]:
    add('appOptimizer','Startup & Processes',n,d,'Caution','medium')

appx=[
('Remove Bing Weather','Microsoft.BingWeather'),('Remove Bing News','Microsoft.BingNews'),('Remove Solitaire Collection','Microsoft.MicrosoftSolitaireCollection'),('Remove Clipchamp','Clipchamp.Clipchamp'),('Remove Get Help','Microsoft.GetHelp'),('Remove Maps','Microsoft.WindowsMaps'),('Remove To Do','Microsoft.Todos'),('Remove Power Automate','Microsoft.PowerAutomateDesktop'),('Remove Feedback Hub','Microsoft.WindowsFeedbackHub'),('Remove Mail & Calendar','microsoft.windowscommunicationsapps'),('Remove Xbox Console Companion','Microsoft.XboxApp'),('Remove Xbox Speech overlay','Microsoft.XboxSpeechToTextOverlay'),('Remove Teams (consumer Chat)','MSTeams'),('Remove Quick Assist','MicrosoftCorporationII.QuickAssist'),('Uninstall Copilot app','Microsoft.Copilot'),('Remove Family Safety','MicrosoftCorporationII.MicrosoftFamily'),('Remove Bing Search app','Microsoft.BingSearch'),('Remove Sticky Notes','Microsoft.MicrosoftStickyNotes'),('Remove 3D Builder','Microsoft.3DBuilder'),('Remove 3D Viewer','Microsoft.Microsoft3DViewer'),('Remove Mixed Reality Portal','Microsoft.MixedReality.Portal'),('Remove Paint 3D','Microsoft.MSPaint'),('Remove People','Microsoft.People'),('Remove Skype','Microsoft.SkypeApp'),('Remove Phone Link','Microsoft.YourPhone'),('Remove Microsoft Journal','Microsoft.MicrosoftJournal'),('Remove Movies & TV','Microsoft.ZuneVideo'),('Remove Groove Music','Microsoft.ZuneMusic'),('Remove Office Hub','Microsoft.MicrosoftOfficeHub'),('Remove OneNote App','Microsoft.Office.OneNote'),('Remove Microsoft Whiteboard','Microsoft.Whiteboard'),('Remove Windows Alarms','Microsoft.WindowsAlarms')]
for name,pkg in appx: add('appRemoval','Preinstalled Apps (current user)',name,f'Removes optional Store package {pkg} for the current user. Reinstall through Microsoft Store.','Caution' if 'Xbox' in name or 'Phone' in name else 'Safe','low',kind='appx',package=pkg)
for n,d,cs in [
('Disable Copilot','Hides legacy Windows Copilot entry point.',[reg(r'HKCU\Software\Policies\Microsoft\Windows\WindowsCopilot','TurnOffWindowsCopilot','REG_DWORD','1')]),('Disable Recall','Windows 11 Recall is managed in Settings (availability varies).',None),('Disable advertising ID','Stops per-user personalized ads.',[reg(A,'Enabled','REG_DWORD','0')]),('Disable Start menu web search','May remove Bing results from Start on supported builds.',[reg(r'HKCU\Software\Policies\Microsoft\Windows\Explorer','DisableSearchBoxSuggestions','REG_DWORD','1')]),('Disable lock screen tips & ads','Removes Spotlight tips and suggestions.',[reg(r'HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager','RotatingLockScreenOverlayEnabled','REG_DWORD','0')]),('Disable suggested content','Turns off suggested apps and tips in Start.',[reg(r'HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager','SubscribedContent-338388Enabled','REG_DWORD','0')])]:
    add('appRemoval','Privacy & Feature Disables',n,d,'Safe','medium',cs)
for n in ['Remove advertising framework','Remove Bing Finance','Disable targeted experiences','Remove Xbox identity provider','Disable People suggestions','Disable news widgets','Turn off consumer data sync','Disable Windows Welcome Experience','Disable recommendations in Explorer','Remove Teams autostart','Disable game capture service','Disable upload telemetry','Disable Maps background updater','Disable location suggestions','Disable device usage suggestions','Remove Windows tips','Disable handwriting telemetry','Disable feedback notifications','Disable recommendations on lock screen','Remove chat button','Disable Spotlight recommendations','Disable shared experience suggestions','Disable online speech suggestions','Disable find my device','Disable settings suggestions','Disable device search suggestions','Disable shared clipboard sync','Disable cloud content search','Disable personalized inking','Disable activity uploads','Disable search highlights','Disable taskbar chat','Disable tailored experiences']:
    add('appRemoval','Privacy & Feature Disables',n,'Preview only: this may affect Windows functionality and varies by Windows release.','Caution','low')

for n in ['SysMain (Superfetch)','Windows Search indexing','Print Spooler','Bluetooth Support','Windows Update','Windows Defender','Network Location Awareness','Diagnostic Policy Service','Xbox Live Networking','Remote Registry','Connected Devices Platform','Windows Error Reporting','Windows Biometric Service']:
    add('services','Services',f'Service: {n}',f'Service configuration for {n}; review whether you rely on it.','Caution','medium',explain='Services control is intentionally not automated because disabling core services can break networking, printing, security and updates.')
for n in ['Memory XMP/EXPO guidance','Enable Resizable BAR guide','UEFI and Secure Boot guide','CPU virtualization settings','Cooling and thermal throttling guide']:
    add('bios','BIOS Guides',n,'Read-only guide: firmware settings must be changed manually after a backup.','Caution','medium',explain='Changing firmware settings automatically is not safe or portable. Consult motherboard documentation.')

assert len(out)==len({i['id'] for i in out}), 'duplicate IDs'
with open('/mnt/data/VioletTweaks/data/tweaks.json','w',encoding='utf-8') as f: json.dump(out,f,ensure_ascii=False,indent=2)
print(len(out),'tweaks:',{k:sum(e['category']==k for e in out) for k in {e['category'] for e in out}})
